const PRIORITY = ['Grief & Loss', 'Shame & Guilt', 'Suffering & Pain', 'Fear', 'Anxiety & Worry', 'Hope', 'Loneliness', 'Forgiveness', 'Faith & Doubt', 'Conflict & Relationships', 'Purpose & Direction', 'Peace'];

